/**
 * Auto-fill for each shopping app's own sign-in page. `autofillStep` runs inside that page (the
 * script text is generated by scripts/generate-provider-readers.cjs), one step per call:
 * open the login form, type the number and request the OTP. The user enters the OTP on that page.
 * It never touches passwords, payment or anything after sign-in.
 */
export type AutofillStep = 'login-opened' | 'phone-filled' | 'waiting-otp' | 'waiting' | 'needs-you'
export interface AutofillState { step: AutofillStep; detail?: string }

export function autofillStep(phone: string, done: string[]): AutofillState {
  const shown = (el: Element) => {
    const h = el as HTMLElement
    if (h.hidden || el.closest('[hidden],[aria-hidden="true"]')) return false
    const st = getComputedStyle(h)
    return st.display !== 'none' && st.visibility !== 'hidden' && !(h as HTMLInputElement).disabled
  }
  const label = (el: Element) => [el.getAttribute('name'), el.id, el.getAttribute('placeholder'), el.getAttribute('aria-label'), el.getAttribute('autocomplete')].join(' ')
  const inputs = Array.from(document.querySelectorAll('input')).filter((i) => shown(i) && !['hidden', 'checkbox', 'radio', 'submit', 'button'].includes(i.type))
  const setValue = (el: HTMLInputElement, v: string) => {
    el.focus()
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set
    if (setter) setter.call(el, v); else el.value = v
    el.dispatchEvent(new Event('input', { bubbles: true }))
    el.dispatchEvent(new Event('change', { bubbles: true }))
    el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: v.slice(-1) }))
  }
  const click = (re: RegExp) => {
    const all = Array.from(document.querySelectorAll('button,[role="button"],input[type="submit"],a,div[tabindex],span[tabindex]'))
    const target = all.find((b) => {
      if (!shown(b)) return false
      const text = ((b as HTMLElement).innerText || (b as HTMLInputElement).value || b.textContent || '').trim().replace(/\s+/g, ' ')
      return text.length > 0 && text.length < 32 && re.test(text) && b.getAttribute('aria-disabled') !== 'true'
    }) as HTMLElement | undefined
    if (target) target.click()
    return !!target
  }
  const notOther = /pin ?code|postal|zip|coupon|promo|referral|search|email|name/i

  // OTP: an autocomplete hint, a field named for it, or a row of single-digit boxes.
  const boxes = inputs.filter((i) => i.maxLength === 1)
  const otpField = inputs.find((i) => /one-time-code|otp|one.?time|verification|\bcode\b/i.test(label(i)) && !notOther.test(label(i)))
  if (otpField || boxes.length >= 4) return { step: 'waiting-otp' }

  if (inputs.some((i) => i.type === 'password')) return { step: 'needs-you', detail: 'This app is asking for a password' }

  const phoneField = inputs.find((i) => (i.type === 'tel' || /phone|mobile/i.test(label(i)) || (i.inputMode === 'numeric' && i.maxLength === 10)) && !(i.maxLength >= 4 && i.maxLength <= 8))
  if (phoneField) {
    // Once only: typing the number again would ask the app for a second OTP.
    if (done.includes('phone')) return { step: 'phone-filled' }
    setValue(phoneField, phone)
    click(/^(continue|get otp|send otp|request otp|login with otp|log ?in|sign ?in|next|proceed|submit)\b/i)
    return { step: 'phone-filled' }
  }

  // Home pages (Blinkit, BigBasket): open the login form once.
  if (!done.includes('opener') && click(/^(log ?in|sign ?in|log ?in ?\/ ?sign ?up|sign ?in ?\/ ?sign ?up|log ?in or sign ?up)$/i)) return { step: 'login-opened' }
  return { step: 'waiting' }
}
